import {fork} from 'node:child_process';
import {writeFileSync} from 'node:fs';

/** External deadline survives a stalled/blocked measurement child. COPY harness only. */
export function runGuarded({script,outputPath,capMs=45000,env={}}){
 return new Promise((resolve,reject)=>{
  const child=fork(script,[],{execArgv:['--experimental-transform-types'],silent:true,detached:process.platform!=='win32',env:{...process.env,...env}});
  const events=[];let timer,timedOut=false,stdout='',stderr='';
  child.stdout.on('data',data=>{stdout+=data;});child.stderr.on('data',data=>{stderr+=data;});
  child.on('message',message=>{
   events.push(message);
   if(message.type==='begin'&&!timer){
    const deadline=message.wallStartedAt+capMs;
    timer=setTimeout(()=>{
     timedOut=true;
     // Kill this owned detached child group before writing partial evidence.
     try {if(process.platform==='win32')child.kill('SIGKILL');else process.kill(-child.pid,'SIGKILL');}catch(error){if(error.code!=='ESRCH')stderr+='\n'+String(error);}
     writeFileSync(outputPath,JSON.stringify({invalid:'External deadline reached; inconclusive, no retry',timedOut:true,capMs,childPID:child.pid,events,stdout,stderr,finishedAt:new Date().toISOString()},null,2)+'\n');
    },Math.max(0,deadline-Date.now()));
    child.send({type:'armed',deadline});
   }
  });
  child.once('error',error=>{clearTimeout(timer);reject(error);});
  child.once('close',(code,signal)=>{
   clearTimeout(timer);
   const result={invalid:timedOut?'External deadline reached; inconclusive, no retry':undefined,timedOut,capMs,childPID:child.pid,exitCode:code,signal,events,stdout,stderr};
   writeFileSync(outputPath,JSON.stringify(result,null,2)+'\n');resolve(result);
  });
 });
}

