export async function verifyFrozen(pin){
 assert.match(pin??'',/^[a-f0-9]{64}$/,'Explicit reviewed frozen-hashes digest required');
 const raw=await readFile(new URL('frozen-hashes.json',import.meta.url));assert.equal(hash(raw),pin);
 const frozen=JSON.parse(raw),actual={};
 for(const [path,expected] of Object.entries(frozen.files)){
  const digest=hash(await readFile(new URL(path,import.meta.url)));assert.equal(digest,expected,'Frozen source changed: '+path);actual[path]=digest;
 }
 return actual;
}

