/** Internal admission bound, independent of the shared physical document reader. */
export function loadDocumentCollection<T>(paths: readonly string[], load: (path: string) => Promise<T>): Promise<T[]> {
  if (paths.length === 0) return Promise.resolve([]);
  return new Promise((resolve, reject) => {
    const values = new Array<T>(paths.length);
    let next = 0;
    let workers = Math.min(64, paths.length);
    let failed = false;

    async function work(): Promise<void> {
      while (next < paths.length) {
        const ordinal = next++;
        try { values[ordinal] = await load(paths[ordinal]!); }
        catch (reason) {
          // Reject immediately, including falsy reasons, but drain every planned path.
          if (!failed) { failed = true; reject(reason); }
        }
      }
      if (--workers === 0 && !failed) resolve(values);
    }

    // Async workers replenish individually; no per-path pending promises or batches.
    for (let index = 0, count = workers; index < count; index++) void work();
  });
}

