import { describe, expect, test } from "bun:test";
import { loadDocumentCollection } from "../src/document-collection.ts";
import { createDocumentReader, type CallbackDocumentReader } from "../src/document-reader.ts";

const turn = async () => { await Promise.resolve(); await Promise.resolve(); };
function controlled() {
  const calls: string[] = [], pending = new Map<string, { resolve: (value: object) => void; reject: (reason: unknown) => void }>();
  let active = 0, peak = 0;
  const load = (path: string) => {
    calls.push(path); active++; peak = Math.max(peak, active);
    return new Promise<object>((resolve, reject) => pending.set(path, {
      resolve: value => { pending.delete(path); active--; resolve(value); },
      reject: reason => { pending.delete(path); active--; reject(reason); },
    }));
  };
  return { calls, pending, load, get active() { return active; }, get peak() { return peak; } };
}

describe("fixed document-operation admission", () => {
  test("replenishes one settlement without a batch barrier and returns original objects in source order", async () => {
    const paths = Array.from({length: 193}, (_, n) => `original/../path-${n}`), c = controlled(), objects = new Map<string, object>();
    const result = loadDocumentCollection(paths, c.load);
    expect(c.calls).toEqual(paths.slice(0, 64)); expect(c.active).toBe(64);
    const first = { path: paths[0] }; objects.set(paths[0]!, first); c.pending.get(paths[0]!)!.resolve(first);
    await turn(); expect(c.calls).toEqual(paths.slice(0, 65)); expect(c.active).toBe(64);
    while (c.pending.size) {
      const [path, deferred] = [...c.pending].at(-1)!;
      const value = { path }; objects.set(path, value); deferred.resolve(value);
      await turn(); expect(c.active).toBeLessThanOrEqual(64);
    }
    const values = await result;
    expect(c.calls).toEqual(paths); expect(new Set(c.calls).size).toBe(193);
    expect(values.every((value, n) => value === objects.get(paths[n]!))).toBe(true);
    expect(c.peak).toBe(64); expect(c.active).toBe(0);
  });

  test("empty and small collections keep their exact path strings and identities", async () => {
    let calls = 0; expect(await loadDocumentCollection([], async () => { calls++; return {}; })).toEqual([]); expect(calls).toBe(0);
    const values = [{id: 1}, {id: 2}], paths = ["relative/../one", "/absolute/two"];
    const seen: string[] = [];
    const result = await loadDocumentCollection(paths, async path => { seen.push(path); return values[paths.indexOf(path)]!; });
    expect(seen).toEqual(paths); expect(result[0]).toBe(values[0]); expect(result[1]).toBe(values[1]);
  });

  test("rejects before drain with exact falsy first reason, then attempts every path and handles later errors", async () => {
    for (const reason of [undefined, null, false, 0, ""]) {
      const paths = Array.from({length: 193}, (_, n) => String(n)), c = controlled(), unhandled: unknown[] = [];
      const listener = (value: unknown) => { unhandled.push(value); }; process.on("unhandledRejection", listener);
      try {
        let fulfilled = false;
        const outcome = loadDocumentCollection(paths, c.load).then(() => { fulfilled = true; return {failed: false, reason: undefined}; }, error => ({failed: true, reason: error}));
        c.pending.get("1")!.reject(reason); const observed = await outcome;
        expect(observed.failed).toBe(true); expect(observed.reason).toBe(reason); expect(fulfilled).toBe(false);
        expect(c.active).toBe(64); expect(c.calls).toHaveLength(65); expect(c.calls.length).toBeLessThan(paths.length);
        while (c.pending.size) {
          const [path, deferred] = [...c.pending].at(-1)!;
          if (Number(path) % 3 === 0) deferred.reject(new Error("later rejection")); else deferred.resolve({path});
          await turn(); expect(c.active).toBeLessThanOrEqual(64);
        }
        await new Promise<void>(resolve => setImmediate(resolve));
        expect(c.calls).toEqual(paths); expect(c.active).toBe(0); expect(unhandled).toEqual([]); expect(fulfilled).toBe(false);
      } finally { process.off("unhandledRejection", listener); }
    }
  });

  test("synchronous throws preserve first reason and long synchronous callbacks never recurse", async () => {
    const c = controlled(), paths = Array.from({length: 193}, (_, n) => String(n)), reason = {first: true};
    const observed = loadDocumentCollection(paths, path => { if (path === "1") throw reason; return c.load(path); }).catch(error => error);
    expect(await observed).toBe(reason); expect(c.active).toBe(64);
    while (c.pending.size) { const [path, deferred] = c.pending.entries().next().value!; deferred.resolve({path}); await turn(); }
    expect(c.calls).toEqual(paths.filter(path => path !== "1")); expect(c.active).toBe(0);
    let depth = 0, peak = 0, calls = 0;
    const long = await loadDocumentCollection(Array.from({length: 20000}, (_, n) => String(n)), path => {
      depth++; peak = Math.max(peak, depth); calls++; depth--; return Promise.resolve(path);
    });
    expect(calls).toBe(20000); expect(peak).toBe(1); expect(long[19999]).toBe("19999");
  });

  test("three operation windows share the unchanged physical FIFO64 reader", async () => {
    const pending = new Map<string, Parameters<CallbackDocumentReader>[1]>(), calls: string[] = [];
    let peak = 0;
    const read = createDocumentReader((path, complete) => { calls.push(path); pending.set(path, complete); peak = Math.max(peak, pending.size); });
    const collections = ["spec", "task", "org"].map(kind => Array.from({length: 97}, (_, n) => `${kind}/${n}`));
    const result = Promise.all(collections.map(paths => loadDocumentCollection(paths, read)));
    expect(pending.size).toBe(64); expect(calls).toHaveLength(64);
    while (pending.size) {
      const [path, complete] = pending.entries().next().value!; pending.delete(path); complete(null, Buffer.from(path));
      await turn(); expect(pending.size).toBeLessThanOrEqual(64);
    }
    const values = await result;
    expect(peak).toBe(64); expect(calls).toHaveLength(291); expect(new Set(calls).size).toBe(291);
    expect(values.map(rows => rows.map(bytes => bytes.toString()))).toEqual(collections);
  });
});
